fn size(o: Option<Vec<Int>>) -> Int {
    match o {
        Some(w) => len(w),
        None => 0,
    }
}

fn main() {
    let v = push(push(vec(), 1), 2);
    let o = Some(v.clone()); // Clone the vector before passing it to size
    print(len(v));
    print(size(o));
}

struct Reading { label: Str, values: Vec<Int> }

fn first_big(v: Vec<Int>) -> Int {
    let found = -1;
    for x in v {
        if x > 10 {
            found = x;
            break;
        }
    }
    found
}

fn second(v: Vec<Int>) -> Option<Int> {
    let x = get(v, 1)?;
    Some(x + 1)
}

fn main() {
    let s = "hello";
    let v = push(push(vec(), "world"), clone(s)); // Clone 's' before moving it
    print(len(v));
    print(str_len(clone(s))); // Clone 's' again to avoid reusing the moved value
}

struct Point { x: Int, tag: Str }

fn main() {
    let p = Point { x: 11, tag: "hello" };
    let q = Point { x: 55, ..p };
    print(str_len(p.tag.clone())); // clone the moved value before using it
    print(q.x);
}

struct Pair { a: Vec<Int>, b: Str }

fn main() {
    let s = Pair { a: push(push(vec(), 1), 2), b: "hello" }
    let Pair { a, b } = s.clone()
    print(len(a))
    print(str_len(b))
    print(str_len(s.b))
}

fn main() {
    let o = Some(concat("ab", "cd"));
    match o {
        Some(s) => print(str_len(s) * 5),
        None => print(0),
    }
    match clone(o) {
        Some(s) => print(str_len(s) * 6),
        None => print(0),
    }
}

fn main() {
    let s = "ab";
    print(str_len(s) * 10);
    let i = 0;
    let total = 0;
    while i < 3 {
        let t = s.clone(); // Clone the string to avoid moving it in a previous iteration
        total = total + str_len(t) * 5;
        i = i + 1;
    }
    print(total);
}

fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v.clone(); // clone at the first consuming use if both are needed
    if flag {
        return len(w) * 10;
    }
    let u = push(v, 3);
    len(u) * 20
}

fn main() {
    print(total(push(push(vec(), 1), 2), true));
    print(total(push(push(vec(), 1), 2), false));
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o?;
    let w = o?;
    Some(len(v) * 10 + len(w))
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

