    let s = "abcdefghij";
    print(str_len(s.clone()));
    let t = concat(s.clone(), s);
    print(str_len(t));
}

fn main() {
    let s = "hello world";
    let n = 42;
    let t = s.clone(); // Clone the string to avoid ownership issues
    print(str_len(t));
    if n > 3 {
        print(str_len(s)); // Now safe to use 's' again
    }
}

fn main() {
    let v = range(0, 10);
    print(len(v));
    let mut total = 0;
    for x in v {
        if x > 4 {
            let w = push(v, x);
            total += len(w);
            break;
        }
    }
    print(total);
}
